package com.infinitylibrary.community;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.gui.LibraryMenu;
import com.infinitylibrary.storage.BookStorageManager.StoredBook;
import net.kyori.adventure.text.Component;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.BookMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.configuration.file.YamlConfiguration;
import java.nio.file.Path;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class ReadingManager {
    public record Progress(int page,int total,boolean completed,String title,long updated){public Progress{if(page<0||total<1||page>=total)throw new IllegalArgumentException("Invalid reading position.");}}
    private record Session(String id,ItemStack held){}
    private final InfinityLibraryPlugin plugin;private final Path file;
    private final Map<UUID,Map<String,Progress>> progress=new HashMap<>();private final Map<UUID,Session> sessions=new HashMap<>();
    public ReadingManager(InfinityLibraryPlugin p){plugin=p;file=p.getDataFolder().toPath().resolve("reading-progress.yml");load();}
    public void load(){
        var y=AtomicYaml.read(file);Map<UUID,Map<String,Progress>> loaded=new HashMap<>();var root=y.getConfigurationSection("players");
        if(root!=null)for(String player:root.getKeys(false)){Map<String,Progress> entries=new HashMap<>();var s=root.getConfigurationSection(player);for(String id:s.getKeys(false)){var b=s.getConfigurationSection(id);entries.put(id,new Progress(b.getInt("page"),b.getInt("total"),b.getBoolean("completed"),b.getString("title","Untitled"),b.getLong("updated")));}loaded.put(UUID.fromString(player),entries);}
        progress.clear();progress.putAll(loaded);sessions.clear();
    }
    public void save(){YamlConfiguration y=new YamlConfiguration();progress.forEach((player,books)->books.forEach((id,b)->{var s=y.createSection("players."+player+"."+id);s.set("page",b.page());s.set("total",b.total());s.set("completed",b.completed());s.set("title",b.title());s.set("updated",b.updated());}));AtomicYaml.write(file,y);}
    public Optional<Progress> progress(UUID player,String id){return Optional.ofNullable(progress.getOrDefault(player,Map.of()).get(id));}
    public void remember(Player p,String id,int page,int total,boolean done,String title){if(total<1)total=1;page=Math.max(0,Math.min(total-1,page));Map<String,Progress> entries=progress.computeIfAbsent(p.getUniqueId(),k->new HashMap<>());Progress old=entries.put(id,new Progress(page,total,done,title,System.currentTimeMillis()));try{save();}catch(RuntimeException ex){if(old==null)entries.remove(id);else entries.put(id,old);throw ex;}}
    private StoredBook stored(Player p,String id){var book=plugin.getBookStorageManager().allBooks().stream().filter(b->b.id().toString().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Book is no longer in the collection."));if(!book.isPublic()&&!book.ownerUuid().equals(p.getUniqueId().toString()))throw new IllegalArgumentException("This book is private.");return book;}
    public void open(Player p,UUID book){stored(p,book.toString());sessions.put(p.getUniqueId(),new Session(book.toString(),null));display(p);}
    public boolean openItem(Player p,ItemStack item){if(item==null||item.getType()!=Material.WRITTEN_BOOK||!(item.getItemMeta() instanceof BookMeta meta))return false;if(!plugin.getBookStorageManager().canRead(p,item))throw new IllegalArgumentException("This book is private.");String tag=meta.getPersistentDataContainer().get(new NamespacedKey(plugin,"library_book_id"),PersistentDataType.STRING);if(tag!=null){try{open(p,UUID.fromString(tag));return true;}catch(IllegalArgumentException ignored){/* Older copy can still be read under its own item permissions. */}}
        var known=plugin.getBookStorageManager().allBooks().stream().filter(b->b.title().equals(Objects.requireNonNullElse(meta.getTitle(),""))&&b.author().equals(Objects.requireNonNullElse(meta.getAuthor(),""))&&b.pages().equals(meta.getPages())&&(b.isPublic()||b.ownerUuid().equals(p.getUniqueId().toString()))).findFirst();if(known.isPresent()){open(p,known.get().id());return true;}
        String owner=meta.getPersistentDataContainer().get(new NamespacedKey(plugin,"book_owner_uuid"),PersistentDataType.STRING);String key="held-"+UUID.nameUUIDFromBytes((Objects.requireNonNullElse(owner,"")+"\0"+meta.getTitle()+"\0"+meta.getAuthor()+"\0"+String.join("\0",meta.getPages())).getBytes(StandardCharsets.UTF_8));sessions.put(p.getUniqueId(),new Session(key,item.clone()));display(p);return true;
    }
    private void display(Player p){Session s=sessions.get(p.getUniqueId());if(s==null)throw new IllegalArgumentException("Open a book first.");List<String> pages;String title,author;if(s.held()==null){var b=stored(p,s.id());pages=b.pages();title=b.title();author=b.author();String credits=b.toItemStack().getItemMeta().getPersistentDataContainer().get(new NamespacedKey(plugin,"book_coauthors"),PersistentDataType.STRING);if(credits!=null&&!credits.isBlank())author+=" · Contributors: "+credits;}else{if(!plugin.getBookStorageManager().canRead(p,s.held()))throw new IllegalArgumentException("This book is private.");var m=(BookMeta)s.held().getItemMeta();pages=m.getPages();title=Objects.requireNonNullElse(m.getTitle(),"Untitled");author=Objects.requireNonNullElse(m.getAuthor(),"");}if(pages.isEmpty())pages=List.of("");int total=pages.size();Progress old=progress(p.getUniqueId(),s.id()).orElse(new Progress(0,total,false,title,0));int page=Math.min(old.page(),total-1);remember(p,s.id(),page,total,old.completed()&&old.total()==total,title);String heading=title+" • "+(page+1)+"/"+total;List<ManagedDialogs.Button> buttons=new ArrayList<>();if(page>0)buttons.add(new ManagedDialogs.Button("Previous",r->turn(p,-1)));if(page<total-1)buttons.add(new ManagedDialogs.Button("Next",r->turn(p,1)));if(page==total-1)buttons.add(new ManagedDialogs.Button(old.completed()?"Mark unread":"Finished reading",r->{var now=progress(p.getUniqueId(),s.id()).orElseThrow();remember(p,s.id(),now.page(),now.total(),!now.completed(),now.title());display(p);}));buttons.add(new ManagedDialogs.Button("Save & close",r->{sessions.remove(p.getUniqueId());browser(p,0,true);}));plugin.getManagedDialogs().show(p,heading,"By "+author+"\n\n"+pages.get(page),List.of(),buttons);}
    public void turn(Player p,int delta){Session s=sessions.get(p.getUniqueId());if(s==null)throw new IllegalArgumentException("No reading session.");if(s.held()==null)stored(p,s.id());var old=progress(p.getUniqueId(),s.id()).orElseThrow();remember(p,s.id(),old.page()+delta,old.total(),old.completed(),old.title());display(p);}
    public void browser(Player p,int page,boolean history){var books=plugin.getBookStorageManager().allBooks().stream().filter(b->b.isPublic()||b.ownerUuid().equals(p.getUniqueId().toString())).filter(b->!history||progress(p.getUniqueId(),b.id().toString()).isPresent()).sorted(history?Comparator.comparingLong((StoredBook b)->progress(p.getUniqueId(),b.id().toString()).map(Progress::updated).orElse(0L)).reversed():Comparator.comparing(StoredBook::title)).toList();page=Math.max(0,Math.min(page,Math.max(0,(books.size()-1)/45)));LibraryMenu m=new LibraryMenu(p,history?LibraryMenu.Screen.READING_HISTORY:LibraryMenu.Screen.READ_CATALOG,54,history?"Library • Continue reading":"Library • Book collection");m.entry(53,Integer.toString(page));var w=plugin.getBookWritingManager();for(int i=0;i<45&&page*45+i<books.size();i++){var b=books.get(page*45+i);m.entry(i,b.id().toString());var saved=progress(p.getUniqueId(),b.id().toString());w.icon(m.getInventory(),i,Material.WRITTEN_BOOK,b.title(),"§7By "+b.author(),"§7"+saved.map(x->x.completed()?"Finished":"Page "+(x.page()+1)+" / "+x.total()).orElse("Not started"),"§eLeft: read · Right: particle route to shelf");}w.icon(m.getInventory(),45,Material.ARROW,"Previous");w.icon(m.getInventory(),46,Material.WRITTEN_BOOK,"Read held book","§7Also remembers pages for books outside the collection");w.icon(m.getInventory(),47,Material.BOOK,history?"All books":"Continue reading");w.icon(m.getInventory(),49,Material.CHEST,"Main menu");w.icon(m.getInventory(),51,Material.ARROW,"Next");p.openInventory(m.getInventory());}
    public void handle(Player p,LibraryMenu m,int slot,boolean right){boolean history=m.screen()==LibraryMenu.Screen.READING_HISTORY;int page=Integer.parseInt(m.entry(53));if(slot<45&&m.entry(slot)!=null){UUID id=UUID.fromString(m.entry(slot));if(right)plugin.getNavigationManager().book(p,id);else open(p,id);}else if(slot==46){if(!openItem(p,p.getInventory().getItemInMainHand()))throw new IllegalArgumentException("Hold a signed book first.");}else if(slot==45)browser(p,page-1,history);else if(slot==51)browser(p,page+1,history);else if(slot==47)browser(p,0,!history);else if(slot==49)plugin.getGuiManager().openMainMenu(p);}
    public void cleanup(Player p){sessions.remove(p.getUniqueId());}
}
